import { describe, expect, it } from 'vitest';

// What App Store Connect needs from the iOS project (docs/playbooks/release-ios.md): a privacy
// manifest in the bundle and a build number that is not the version. The
// xcodegen project is committed and regenerated by hand, so this gate keeps project.yml, the
// generated project and the generated Info.plist saying the same thing.
//
// The files sit outside src/ and the frontend tsconfig has no Node typings, so fs is imported
// through a variable specifier and typed by hand (the pattern of src/index.test.ts).
type Fs = { readFileSync(url: URL, encoding: 'utf8'): string };
const fsSpecifier = 'node:fs';
const { readFileSync } = (await import(/* @vite-ignore */ fsSpecifier)) as Fs;

const TAURI = new URL('../../src-tauri/', import.meta.url);
const APPLE = new URL('gen/apple/', TAURI);
const read = (path: string, base: URL = APPLE) => readFileSync(new URL(path, base), 'utf8');

/** The `<string>` value that follows `<key>name</key>` in a plist. */
function plistString(plist: string, name: string): string | undefined {
  return plist.match(new RegExp(`<key>${name}</key>\\s*<string>([^<]*)</string>`))?.[1];
}

/** The reason codes a privacy manifest declares for one category of required-reason API. */
function reasonsOf(manifest: string, category: string): string[] {
  const entry = manifest.match(
    new RegExp(
      `<string>${category}</string>\\s*<key>NSPrivacyAccessedAPITypeReasons</key>\\s*<array>([\\s\\S]*?)</array>`
    )
  );
  return [...(entry?.[1] ?? '').matchAll(/<string>([^<]+)<\/string>/g)].map((m) => m[1]);
}

describe('the iOS project, as App Store Connect needs it', () => {
  it('bundles the privacy manifest', () => {
    const pbx = read('moony.xcodeproj/project.pbxproj');
    expect(pbx).toContain('PrivacyInfo.xcprivacy in Resources */ = {isa = PBXBuildFile;');
    expect(pbx).toMatch(/files = \([^)]*PrivacyInfo\.xcprivacy in Resources \*\//);
    // xcodegen takes it from the moony_iOS source folder
    const yml = read('project.yml');
    expect(yml.slice(yml.indexOf('\n  moony_iOS:'))).toMatch(/^\s+- path: moony_iOS\s*$/m);
  });

  it('the privacy manifest declares no tracking, no collected data and the two API categories', () => {
    const manifest = read('moony_iOS/PrivacyInfo.xcprivacy');
    expect(manifest).toMatch(/<key>NSPrivacyTracking<\/key>\s*<false\/>/);
    expect(manifest).toMatch(/<key>NSPrivacyTrackingDomains<\/key>\s*<array\/>/);
    expect(manifest).toMatch(/<key>NSPrivacyCollectedDataTypes<\/key>\s*<array\/>/);
    expect(reasonsOf(manifest, 'NSPrivacyAccessedAPICategoryFileTimestamp')).toEqual([
      'C617.1',
      '3B52.1',
    ]);
    expect(reasonsOf(manifest, 'NSPrivacyAccessedAPICategoryDiskSpace')).toEqual(['E174.1']);
    expect(manifest.match(/<key>NSPrivacyAccessedAPIType<\/key>/g)?.length).toBe(2);
  });

  it('keeps the build number apart from the version', () => {
    const ios = JSON.parse(read('tauri.ios.conf.json', TAURI)) as {
      bundle: { iOS: { bundleVersion: string } };
    };
    const local = ios.bundle.iOS.bundleVersion;
    // One integer: Apple reads at most three dot-separated ones, and the store build passes its own
    expect(local).toMatch(/^[1-9]\d*$/);
    const info = read('moony_iOS/Info.plist');
    expect(plistString(info, 'CFBundleVersion')).toBe(local);
    expect(read('project.yml')).toContain(`CFBundleVersion: "${local}"`);

    const { version } = JSON.parse(read('tauri.conf.json', TAURI)) as { version: string };
    expect(plistString(info, 'CFBundleShortVersionString')).toBe(version);
    expect(read('project.yml')).toMatch(
      new RegExp(`^\\s+CFBundleShortVersionString: ${version.replace(/\./g, '\\.')}\\s*$`, 'm')
    );
  });

  it('a device install keeps its own export method', () => {
    expect(plistString(read('ExportOptions.plist'), 'method')).toBe('debugging');
  });
});
